&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Balafr&#233;-Enrag&#233;-(Barbare).html&quot; title=&quot;Balafr&#233; enrag&#233;&quot;&gt;Balafr&#233; enrag&#233;&lt;/a&gt; (UC)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barbare-Sauvage-(Barbare).html&quot; title=&quot;Barbare sauvage&quot;&gt;Barbare sauvage&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barbare-Urbain-(Barbare).html&quot; title=&quot;Barbare urbain&quot;&gt;Barbare urbain&lt;/a&gt; (UC)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Briseur-De-Titan-(Barbare).html&quot; title=&quot;Briseur de titan&quot;&gt;Briseur de titan&lt;/a&gt; (UC)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brute-Avin&#233;e-(Barbare).html&quot; title=&quot;Brute avin&#233;e&quot;&gt;Brute avin&#233;e&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Carcasse-M&#233;tallique-(Barbare).html&quot; title=&quot;Carcasse m&#233;tallique&quot;&gt;Carcasse m&#233;tallique&lt;/a&gt; (UC)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chien-Enrag&#233;-(Barbare).html&quot; title=&quot;Chien enrag&#233;&quot;&gt;Chien enrag&#233;&lt;/a&gt; (AA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Concasseur-(Barbare).html&quot; title=&quot;Concasseur&quot;&gt;Concasseur&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;voreur-De-Chair-(Barbare).html&quot; title=&quot;D&#233;voreur de chair&quot;&gt;D&#233;voreur de chair&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enrag&#233;-De-La-Meute-(Barbare).html&quot; title=&quot;Enrag&#233; de la meute&quot;&gt;Enrag&#233; de la meute&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gnoll.html&quot; title=&quot;Gnoll&quot;&gt;Gnoll&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enrag&#233;-Haineux-(Barbare).html&quot; title=&quot;Enrag&#233; haineux&quot;&gt;Enrag&#233; haineux&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;Demi-orque&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fr&#232;re-&#201;l&#233;mentaire-(Barbare).html&quot; title=&quot;Fr&#232;re &#233;l&#233;mentaire&quot;&gt;Fr&#232;re &#233;l&#233;mentaire&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Furie-Mont&#233;e-(Barbare).html&quot; title=&quot;Furie mont&#233;e&quot;&gt;Furie mont&#233;e&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grinceur-Sauvage-(Barbare).html&quot; title=&quot;Grinceur sauvage&quot;&gt;Grinceur sauvage&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelin-(Race).html&quot; title=&quot;Les gobelins&quot;&gt;Gobelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-Totem-(Barbare).html&quot; title=&quot;Guerrier totem&quot;&gt;Guerrier totem&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invuln&#233;rable-Enrag&#233;-(Barbare).html&quot; title=&quot;Invuln&#233;rable enrag&#233;&quot;&gt;Invuln&#233;rable enrag&#233;&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lanceur-(Barbare).html&quot; title=&quot;Lanceur&quot;&gt;Lanceur&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pugiliste-Brutal-(Barbare).html&quot; title=&quot;Pugiliste brutal&quot;&gt;Pugiliste brutal&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sauvage-Enrag&#233;-(Barbare).html&quot; title=&quot;Sauvage enrag&#233;&quot;&gt;Sauvage enrag&#233;&lt;/a&gt; (UC)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Superstitieux-(Barbare).html&quot; title=&quot;Superstitieux&quot;&gt;Superstitieux&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Terreur-Des-Mers-(Barbare).html&quot; title=&quot;Terreur des mers&quot;&gt;Terreur des mers&lt;/a&gt; (UC)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;V&#233;ritable-Primitif-(Barbare).html&quot; title=&quot;V&#233;ritable primitif&quot;&gt;V&#233;ritable primitif&lt;/a&gt; (UC)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Tous les barbares ne chassent pas dans les plaines, les for&#234;ts ou les montagnes. Certains sont de terrifiants pirates qui pillent les mers et les c&#244;tes, d&#233;pouillent tous ceux qui poss&#232;dent un tr&#233;sor ou pourchassent les monstres des profondeurs. Certains ne sont gu&#232;re plus que des chasseurs de haute mer mais d’autres sont des pillards qui s&#232;ment la terreur dans les villages c&#244;tiers &#224; port&#233;e de leurs drakkars.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes et armures&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_et_armures_0&quot; href=&quot;#Armes_et_armures_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Une terreur des mers n’est pas form&#233;e au port de l’armure interm&#233;diaire.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Terreur marine (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Terreur_marine_Ext_1&quot; href=&quot;#Terreur_marine_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Une terreur des mers peut retenir son souffle pendant un nombre de rounds &#233;gal &#224; quatre fois sa valeur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt;. De plus, elle se d&#233;place normalement dans les cases d’eau stagnante et de tourbi&#232;re de moins de 30 cm de profondeur. Elle n’a pas besoin de payer un co&#251;t suppl&#233;mentaire en mouvement pour se d&#233;placer dans ces zones. Enfin, elle ignore le bonus d’abri &#224; la CA dont disposent habituellement les cr&#233;atures partiellement immerg&#233;es. Ce pouvoir remplace le &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#DEPLACEMENTACCELERE&quot; title=&quot;Le barbare&quot;&gt;d&#233;placement acc&#233;l&#233;r&#233;&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Yeux de la temp&#234;te (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Yeux_de_la_temp&#234;te_Ext_2&quot; href=&quot;#Yeux_de_la_temp&#234;te_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 2, la terreur des mers ignore le camouflage qui r&#233;sulte du brouillard, de la pluie, de la neige fondue, de la brume, du vent ou d’un autre effet m&#233;t&#233;orologique (sauf s’il donne un camouflage total). Tous les malus aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; qui d&#233;coulent de la m&#233;t&#233;o sont r&#233;duits de moiti&#233;. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Roublard#Esquiveinstinctive.html&quot; title=&quot;esquive instinctive&quot;&gt;esquive instinctive&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Marin sauvage (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Marin_sauvage_Ext_3&quot; href=&quot;#Marin_sauvage_Ext_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 3, la terreur des mers gagne un bonus de +1 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt;, d’&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Profession.html&quot; title=&quot;Profession&quot;&gt;Profession&lt;/a&gt; (marin) et de &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; quand elle se trouve en terrain aquatique (y compris &#224; bord d’un bateau ou sur la c&#244;te). Apr&#232;s le niveau 3, ce bonus augmente de +1 tous les trois niveaux. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Roublard#Sensdespieges.html&quot; title=&quot;sens des pi&#232;ges&quot;&gt;sens des pi&#232;ges&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pied s&#251;r (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Pied_s&#251;r_Ext_4&quot; href=&quot;#Pied_s&#251;r_Ext_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 5, la terreur des mers ne subit pas de malus quand elle se d&#233;place sur une surface glissante, naturelle ou magique (comme graisse, temp&#234;te de gr&#234;le ou temp&#234;te de neige). Dans ces zones, elle ne risque pas de tomber et ne perd pas son bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt;. Elle ne consid&#232;re pas ces terrains comme difficiles. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Roublard#Esquiveinstinctivesuperieure.html&quot; title=&quot;esquive instinctive sup&#233;rieure&quot;&gt;esquive instinctive sup&#233;rieure&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pouvoirs de rage&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoirs_de_rage_5&quot; href=&quot;#Pouvoirs_de_rage_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici les pouvoirs de rage qui viennent compl&#233;ter l’arch&#233;type de terreur des mers : &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage#Fracassement.html&quot; title=&quot;Fracassement (rage)&quot;&gt;fracassement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage#Nageenrage.html&quot; title=&quot;Nage en rage (rage)&quot;&gt;nage en rage&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage#Nageurbestial.html&quot; title=&quot;nageur bestial&quot;&gt;nageur bestial&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage#Projectileencharge.html&quot; title=&quot;Projectile en charge (rage)&quot;&gt;projectile en charge&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage#Rouleboule.html&quot; title=&quot;Roul&#233;-boul&#233; (rage)&quot;&gt;roul&#233;-boul&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage#Sautenrage.html&quot; title=&quot;Saut en rage (rage)&quot;&gt;saut en rage&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage#Sauteurbestial.html&quot; title=&quot;sauteur bestial&quot;&gt;sauteur bestial&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage#Viensmattraper.html&quot; title=&quot;Viens mattraper (rage)&quot;&gt;viens m’attraper&lt;/a&gt;.
